import {participantRole,setTravelMode,saveVehicleAssignments,vehicleForPerson,vehicleKey,validateAssignments} from './transport.mjs';
import {rosterRows,resetWithRoster,cachedRoster} from './roster.mjs';
import {extractDocument} from './document-reader.mjs';
import {csvRecords,normalize,pendingItems} from './core.mjs';
import {syncDetectedParticipants,removeParticipant} from './document-model.mjs';
import {renderDashboard} from './trip-dashboard.mjs';
import {createDocumentFeatures} from './document-ui.mjs';
const $=s=>document.querySelector(s),uid=()=>crypto.randomUUID(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rosterTarget=null;
let dashboardFilter='all';
let db,state={trips:[]},selected=null,tab='overview',submitAction=null,importKind='people',folderTarget=null,toastTimer;
const dbReady=new Promise((resolve,reject)=>{const r=indexedDB.open('equip-viatges-v0',1);r.onupgradeneeded=()=>{r.result.createObjectStore('data');r.result.createObjectStore('folders');};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)});
async function read(store,key){await dbReady;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function write(store,key,value){await dbReady;return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function remove(store,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function persist(){await write('data','state',state);render()}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5500)}
function fail(e){console.error(e);toast(e.name==='QuotaExceededError'?'Emmagatzematge ple. Prova amb una carpeta més petita.':e.message||'No s’ha pogut completar l’operació.')}
const trip=()=>state.trips.find(t=>t.id===selected),date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('ca-ES',{day:'numeric',month:'short',year:'numeric'}):'Dates per confirmar';
const badge=s=>`<span class="status ${['Comprat','Fet','Reservat'].includes(s)?'done':s==='No cal'?'neutral':''}">${esc(s==='Comprat'?'OK · Comprat':s||'Pendent')}</span>`;
const sport=s=>`<span class="pill ${s==='Ciclisme'?'cycle':''}">${s==='Ciclisme'?'↗':'❄'} ${esc(s)}</span>`;
const empty=(title,description,button='')=>`<div class="empty"><div class="empty-icon">▤</div><h3>${title}</h3><p>${description}</p>${button}</div>`;
function render(){const t=trip();$('#crumb').textContent=t?t.name:'Viatges';if(!t){selected=null;renderHome();return}renderTrip(t)}
function renderHome(){const pending=state.trips.reduce((n,t)=>n+pendingItems(t).length,0);$('#app').innerHTML=`<div class="page-head"><div><h1>Els teus viatges</h1><p>Tota la logística de l’equip, en un mateix lloc.</p></div><button class="button" data-action="new-trip">＋ Nou viatge</button></div><div class="stats"><div class="stat"><span>Viatges organitzats</span><strong>${state.trips.length}</strong></div><div class="stat"><span>Participants</span><strong>${state.trips.reduce((n,t)=>n+t.people.length,0)}</strong></div><div class="stat"><span>Gestions pendents</span><strong>${pending}<small>per revisar</small></strong></div></div><div class="section-head"><h2>Viatges</h2><span class="muted small">${state.trips.length} en aquest espai</span></div>${state.trips.length?`<div class="grid">${state.trips.map(t=>`<button class="trip-card" data-action="open-trip" data-id="${t.id}"><div class="trip-top">${sport(t.sport)}<span class="muted">↗</span></div><div class="trip-content"><h3>${esc(t.name)}</h3><p>⌖ ${esc(t.destination||'Destinació per confirmar')}</p><p>${date(t.start)}${t.end?' — '+date(t.end):''}</p></div><div class="trip-footer"><span>${t.people.length} participants · ${t.vehicles.length} vehicles</span><span>${t.folder?'▣ Carpeta':'Sense carpeta'}</span></div></button>`).join('')}</div>`:empty('El primer viatge comença aquí','Crea un viatge, vincula la seva carpeta i afegeix-hi les persones i els transports.','<button class="button" data-action="new-trip">＋ Crear el primer viatge</button>')}<div class="notice"><strong>El teu espai de treball local.</strong> Els documents es llegeixen només amb el teu permís. Les dades d’aquesta versió es guarden en aquest navegador, no es comparteixen amb l’equip. Exporta una còpia abans de canviar d’ordinador o esborrar les dades del navegador.</div><div class="mobile-backup actions"><button class="button secondary" data-action="backup">Exportar dades</button><button class="button secondary" data-action="restore">Restaurar còpia</button></div>`}
function renderTrip(t){$('#app').innerHTML=`<button class="back" data-action="home">← Tots els viatges</button><div class="page-head"><div>${sport(t.sport)}<h1 style="margin-top:12px">${esc(t.name)}</h1><p>${esc(t.destination||'Destinació per confirmar')} · ${date(t.start)}${t.end?' — '+date(t.end):''}</p></div><div class="actions"><button class="button secondary" data-action="edit-trip">Editar viatge</button></div></div><nav class="tabs" aria-label="Seccions del viatge">${[['overview','Resum'],['people','Participants',t.people.length],['vehicles','Transports',t.vehicles.length],['files','Documents',t.files.length]].map(([key,label,n])=>`<button class="tab ${tab===key?'active':''}" data-action="tab" data-id="${key}" aria-current="${tab===key?'page':'false'}">${label}${n!==undefined?' · '+n:''}</button>`).join('')}</nav><div id="tripContent">${tab==='overview'?overview(t):tab==='people'?people(t):tab==='vehicles'?vehicles(t):files(t)}</div>`}
function folderPanel(t){return `<div class="folder-panel"><div class="folder-icon">▣</div><div><h3>${esc(t.folder?.name||'Vincula la carpeta del viatge')}</h3><p>${t.folder?`${t.files.length} documents · ${t.folder.mode==='handle'?'Lectura amb permís':'Còpia local al navegador'}`:'Selecciona una carpeta del teu ordinador per tenir els documents a mà.'}</p>${t.folder?`<p>Última lectura: ${new Date(t.folder.updated).toLocaleString('ca-ES')}</p>`:''}</div><div class="actions">${t.folder?'<button class="button lime" data-action="refresh-folder">↻ Actualitzar</button>':''}<button class="button ${t.folder?'secondary':'lime'}" data-action="link-folder">${t.folder?'Canviar carpeta':'Vincular carpeta'}</button></div></div>`}
function rosterPanel(t){return `<div class="notice"><strong>1. Excel de participants → 2. Carpeta de documents</strong><p>${t.rosterSource?esc(t.rosterSource)+' · '+t.people.length+' participants':'Importa l’Excel amb la llista oficial. Després selecciona la carpeta per associar les reserves.'}</p><div class="actions"><button class="button" data-action="import-roster">Importar Excel de participants</button><button class="button secondary" data-action="reset-roster">Reiniciar amb l’Excel llegit</button></div></div>`}
function rosterPreview(t,rows,source){modal('Reiniciar amb '+rows.length+' participants',`<p>Es substituirà la llista d’aquest viatge pels participants de <strong>${esc(source)}</strong>.</p><div class="notice">S’esborraran les associacions, els estats de bitllet i check-in i la vinculació amb la carpeta. Després podràs seleccionar la carpeta de nou. Els documents originals no es modifiquen.</div><div class="csv-preview"><ul>${rows.map(p=>`<li>${esc(p.name)}${p.role?' · '+esc(p.role):''}</li>`).join('')}</ul></div>`,async()=>{const draft=resetWithRoster(t,rows,source),next={...state,trips:state.trips.map(x=>x.id===t.id?draft:x)};await new Promise((resolve,reject)=>{const tx=db.transaction(['data','folders'],'readwrite');tx.objectStore('data').put(t,'before-roster-reset:'+t.id);tx.objectStore('data').put(next,'state');tx.objectStore('folders').delete(t.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});state=next;tab='overview';dashboardFilter='all';render();toast(rows.length+' participants preparats. Ara selecciona la carpeta dels documents.')},'Reiniciar i posar els '+rows.length+' participants')}
function overview(t){const items=pendingItems(t);return `${renderDashboard(t,dashboardFilter,esc)}${rosterPanel(t)}${folderPanel(t)}${documents.pending(t)?`<div class="notice">${documents.pending(t)} documents per revisar. <button class="text-button" data-action="tab" data-id="files">Revisar documents →</button></div>`:''}<div class="stats"><div class="stat"><span>Participants</span><strong>${t.people.length}</strong></div><div class="stat"><span>Vehicles</span><strong>${t.vehicles.length}</strong></div><div class="stat"><span>Gestions pendents</span><strong>${items.length}</strong></div></div><div class="split"><section class="panel"><h3>Per deixar-ho tot a punt</h3>${items.length?`<ul class="pending-list">${items.map(s=>`<li><b>!</b> ${esc(s)}</li>`).join('')}</ul>`:`<p class="muted">${t.people.length?'No hi ha gestions pendents en les fitxes actuals.':'Afegeix els participants per començar a revisar els bitllets, el check-in i els transports.'}</p>`}<button class="text-button" data-action="tab" data-id="people">Gestionar participants →</button></section><section class="panel"><h3>Informació del viatge</h3><dl class="detail-list"><div><dt>Responsable</dt><dd>${esc(t.coordinator||'Per assignar')}</dd></div><div><dt>Telèfon</dt><dd>${esc(t.phone||'Sense indicar')}</dd></div><div><dt>Allotjament</dt><dd>${esc(t.hotel||'Sense indicar')}</dd></div><div><dt>Equip</dt><dd>${esc(t.sport)}</dd></div></dl>${t.notes?`<p class="small" style="white-space:pre-wrap">${esc(t.notes)}</p>`:''}</section></div>`}
function people(t){return `<div class="section-head"><h2>Participants</h2><div class="actions"><button class="button" data-action="import-roster">Importar Excel de participants</button><button class="button secondary" data-action="reset-roster">Reiniciar amb l’Excel llegit</button></div></div>${t.people.length?`<div class="table-wrap"><table><thead><tr><th>PERSONA / ORIGEN</th><th>BITLLET</th><th>CHECK-IN</th><th>ARRIBADA</th><th>TRANSPORT / RECOLLIDA</th><th></th></tr></thead><tbody>${t.people.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(participantRole(p.role))} · ${esc(p.travelMode||'Avió')}</small>${documents.personStatus(t,p)}${documents.journeySummary(t,p)}${documents.personSummary(t,p)}${documents.purchaseSummary(p)}<small>${documents.originSummary(t,p)}${p.phone?' · '+esc(p.phone):''}</small></td><td>${badge(p.ticket)}</td><td><button class="text-button" data-action="person-checkin" data-id="${p.id}" aria-label="Veure dades de check-in de ${esc(p.name)}">${badge(p.checkin)} ↗</button></td><td>${documents.arrivalSummary(t,p)}</td><td>${esc(t.vehicles.find(v=>v.id===p.vehicle)?.name||p.pickup||'Per assignar')}<small>${esc(p.parking||'')}</small></td><td><button class="edit-button" data-action="edit-person" data-id="${p.id}">Editar</button><button class="edit-button" data-action="participant-itinerary" data-id="${p.id}">Itinerari</button></td></tr>`).join('')}</tbody></table></div>`:empty('Qui viatja amb l’equip?','Importa l’Excel amb la llista oficial abans de seleccionar la carpeta de documents.','<button class="button" data-action="import-roster">Importar Excel de participants</button>')}<p class="muted small">Les reserves de compra identificades marquen el bitllet com a OK. Clica el check-in per veure el localitzador, l’email i l’enllaç de la companyia.</p>`}
function vehicles(t){return `<div class="section-head"><h2>Transports</h2><div class="actions"><button class="button secondary" data-action="template" data-id="vehicles">Plantilla CSV ↓</button><button class="button secondary" data-action="import" data-id="vehicles">Importar CSV</button><button class="button" data-action="new-vehicle">＋ Vehicle</button></div></div>${t.vehicles.length?`<div class="grid">${t.vehicles.map(v=>{const ps=t.people.filter(p=>p[vehicleKey(v.direction)]===v.id);return `<section class="panel"><div class="section-head" style="margin-top:0"><h3>${esc(v.name)}</h3><span class="pill">${esc(v.direction)}</span></div><dl class="detail-list"><div><dt>Conductor</dt><dd>${esc(v.driver||'Per assignar')}</dd></div><div><dt>Telèfon</dt><dd>${esc(v.phone||'Sense indicar')}</dd></div><div><dt>Sortida</dt><dd>${esc(v.origin||'Per confirmar')}</dd></div><div><dt>Hora</dt><dd>${esc(v.departure||'Per confirmar')}</dd></div><div><dt>Places per a passatgers</dt><dd>${v.seats||'Sense indicar'}</dd></div><div><dt>Aparcament</dt><dd>${esc(v.parking||'Sense indicar')}</dd></div></dl><p class="small"><strong>Passatgers assignats:</strong> ${ps.length?ps.map(p=>esc(p.name)).join(', '):'Cap'}</p>${v.passengers?`<p class="small"><strong>Passatgers indicats al CSV:</strong> ${esc(v.passengers)}</p>`:''}${v.pickupLocation||v.pickupTime?`<p><strong>Recollida:</strong> ${esc(v.pickupLocation||'Lloc pendent')} · ${esc(v.pickupTime||'Hora pendent')}</p>`:''}${v.notes?`<p class="small muted">${esc(v.notes)}</p>`:''}<button class="edit-button" data-action="edit-vehicle" data-id="${v.id}">Editar transport</button></section>`}).join('')}</div>`:empty('Cada trajecte, ben organitzat','Crea un vehicle per trajecte: anada o tornada. Indica el conductor, la sortida, l’hora i les places.','<button class="button" data-action="new-vehicle">＋ Afegir vehicle</button>')}`}
function files(t){return `${folderPanel(t)}${documents.panel(t)}<div class="notice">${t.folder?.mode==='handle'?'La carpeta es rellegeix amb «Actualitzar».':'Torna a seleccionar la carpeta per actualitzar-ne la còpia local.'} Els fitxers nous es llegeixen automàticament. No s’envia cap document a un servidor.</div>${t.files.length?`<div class="table-wrap"><table><thead><tr><th>DOCUMENT</th><th>LECTURA / PERSONES</th><th>MIDA</th><th></th></tr></thead><tbody>${t.files.map((f,i)=>`<tr><td class="file-path"><strong>${esc(f.name)}</strong><small>${esc(f.path)}</small></td><td>${documents.status(t,f)}</td><td class="nowrap">${formatSize(f.size)}</td><td><div class="row-links"><button class="edit-button" data-action="review-document" data-id="${esc(f.path)}">Revisar / associar</button><button class="edit-button" data-action="download-file" data-id="${i}">Descarregar</button>${/\.(csv|tsv)$/i.test(f.name)?`<button class="edit-button" data-action="import-file" data-id="${i}">Importar dades</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Els documents del viatge','Vincula una carpeta. Llegirem els noms i els trajectes per proposar-te a qui correspon cada document.')}`}

function formatSize(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB'}
function field(label,key,value='',type='text',full=false,required=false){return `<label class="field ${full?'full':''}">${label}<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`}
function select(label,key,value,options){return `<label class="field">${label}<select name="${key}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
function notes(value){return `<label class="field full">Notes<textarea name="notes">${esc(value||'')}</textarea></label>`}
function modal(title,html,fn,label='Guardar'){$('#modal').classList.remove('document-modal');submitAction=fn;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#submitModal').textContent=label;$('#modal').showModal()}
function tripForm(edit=false){const t=edit?trip():{};modal(edit?'Editar viatge':'Nou viatge',`<div class="form-grid">${field('Nom del viatge','name',t.name,'text',true,true)}${select('Equip','sport',t.sport||'Esquí',['Esquí','Ciclisme'])}${field('Destinació','destination',t.destination)}${field('Data de sortida','start',t.start,'date')}${field('Data de tornada','end',t.end,'date')}${field('Responsable','coordinator',t.coordinator)}${field('Telèfon','phone',t.phone,'tel')}${field('Allotjament','hotel',t.hotel,'text',true)}${notes(t.notes)}</div>`,async data=>{if(data.start&&data.end&&data.end<data.start)throw Error('La tornada no pot ser anterior a la sortida.');if(edit)Object.assign(t,data);else{const n={...data,id:uid(),rosterMode:'excel',people:[],vehicles:[],files:[],folder:null};state.trips.push(n);selected=n.id;tab='overview'}await persist();toast(edit?'Viatge actualitzat':'Viatge creat. Ja pots vincular-hi una carpeta.')})}
function personForm(id){const t=trip();if(!id&&t.rosterMode==='excel'){handlers['import-roster']();return}const p=t.people.find(p=>p.id===id)||{};modal(id?'Editar participant':'Nou participant',`<div class="form-grid">${field('Nom i cognoms','name',p.name,'text',true,true)}${select('Rol a l’equip','role',participantRole(p.role),['Esportista','Tècnic','Fisio','Altres'])}${select('Com viatja','travelMode',p.travelMode||'Avió',['Avió','Cotxe','Per decidir'])}${field('Email personal · futur accés','email',p.email,'email')}${field('Telèfon','phone',p.phone,'tel')}${field('Origen','origin',p.origin)}${select('Bitllet','ticket',p.ticket||'Pendent',['Pendent','Comprat','No cal'])}${select('Check-in','checkin',p.checkin||'Pendent',['Pendent','Fet','No cal'])}${field('Arribada · dia, hora i lloc','arrival',p.arrival,'text',true)}${select('Vehicle assignat','vehicle',p.vehicle||'',[['','Sense assignar'],...t.vehicles.filter(v=>v.direction!=='Tornada').map(v=>[v.id,`${v.name} · ${v.direction}`])])}${select('Vehicle de tornada','returnVehicle',p.returnVehicle||'',[['','Sense assignar'],...t.vehicles.filter(v=>v.direction==='Tornada').map(v=>[v.id,v.name])])}${field('Recollida · persona i lloc','pickup',p.pickup)}${field('Aparcament','parking',p.parking,'text',true)}${notes(p.notes)}</div>${id?documents.journeySummary(t,p)+documents.personSummary(t,p)+`<button type="button" class="button secondary" data-action="participant-itinerary" data-id="${p.id}">Veure itinerari individual</button>`:''}${id?'<button type="button" class="text-button error" data-action="delete-person" data-id="'+id+'">Eliminar participant</button>':''}`,async data=>{if(id){const check=structuredClone(t);Object.assign(check.people.find(x=>x.id===id),data);validateAssignments(check);if(data.ticket!==p.ticket)p.ticketSource='manual';const mode=data.travelMode;delete data.travelMode;Object.assign(p,data);setTravelMode(p,mode)}else t.people.push({...data,id:uid()});await persist();toast('Participant guardat')})}
function vehicleForm(id){const t=trip(),v=t.vehicles.find(v=>v.id===id)||{};modal(id?'Editar transport':'Nou transport',`<div class="form-grid">${field('Vehicle · nom o matrícula','name',v.name,'text',false,true)}${select('Trajecte','direction',v.direction||'Anada',['Anada','Tornada'])}${select('Conductor · participant','driverId',v.driverId||'',[['','Conductor extern'],...t.people.map(p=>[p.id,p.name+' · '+participantRole(p.role)])])}${field('Nom del conductor extern','driver',v.driver)}${field('Telèfon del conductor','phone',v.phone,'tel')}${field('Punt de sortida','origin',v.origin)}${field('Dia i hora de sortida','departure',v.departure)}${field('Places per a passatgers (sense conductor)','seats',v.seats||'','number')}${field('Aparcament / reserva','parking',v.parking)}${field('Aeroport / punt de recollida','pickupLocation',v.pickupLocation)}${field('Hora de recollida','pickupTime',v.pickupTime)}${field('Passatgers indicats / anotacions','passengers',v.passengers,'text',true)}<fieldset class="field full"><legend>Assignar passatgers a aquest vehicle</legend>${t.people.map(p=>`<label class="check-label"><input type="checkbox" name="passenger_${p.id}" ${p[vehicleKey(v.direction)]===v.id&&v.id?'checked':''}>${esc(p.name)} · ${esc(participantRole(p.role))}</label>`).join('')}</fieldset>${notes(v.notes)}</div><p class="small muted">Selecciona els passatgers d’aquest trajecte. El conductor viatja amb cotxe i no ocupa una plaça de passatger. Les assignacions d’anada i tornada són independents.</p>${id?'<button type="button" class="text-button error" data-action="delete-vehicle" data-id="'+id+'">Eliminar vehicle</button>':''}`,async data=>{data.seats=Number(data.seats)||0;const ids=Object.keys(data).filter(k=>k.startsWith('passenger_')).map(k=>k.slice(10));for(const k of Object.keys(data))if(k.startsWith('passenger_'))delete data[k];const draft=saveVehicleAssignments(t,{...data,id:id||uid()},ids);await saveTrip(draft);toast('Transport i passatgers assignats')})}
async function scan(handle){const out=[];async function walk(dir,prefix=''){for await(const [name,entry]of dir.entries()){if(name.startsWith('.'))continue;const path=prefix+name;if(entry.kind==='directory')await walk(entry,path+'/');else{if(out.length>=2000)throw Error('La carpeta supera els 2.000 fitxers. Selecciona una carpeta específica del viatge.');const f=await entry.getFile();out.push({name,path,size:f.size,modified:f.lastModified})}}}await walk(handle);return out.sort((a,b)=>a.path.localeCompare(b.path))}
async function linkFolder(){const t=trip();if(!t.people.length){toast('Importa primer l’Excel de participants.');return}if(!window.showDirectoryPicker){folderTarget=t.id;$('#folderInput').click();return}try{const handle=await window.showDirectoryPicker({mode:'read'});toast('Llegint la carpeta…');const list=await scan(handle);await write('folders',t.id,{handle});t.folder={name:handle.name,mode:'handle',updated:Date.now()};t.files=list;await persist();await documents.analyze(t)}catch(e){if(e.name!=='AbortError'){if(e.name==='SecurityError'){folderTarget=t.id;$('#folderInput').click()}else fail(e)}}}
async function refreshFolder(){const t=trip();if(!t.folder||t.folder.mode!=='handle'){folderTarget=t.id;$('#folderInput').click();return}const saved=await read('folders',t.id);if(!saved?.handle){toast('Torna a seleccionar la carpeta per recuperar l’accés.');return linkFolder()}if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís de lectura a la carpeta.');toast('Actualitzant documents…');const list=await scan(saved.handle);t.files=list;t.folder.updated=Date.now();await persist();await documents.analyze(t)}
async function localFile(t,index){const meta=t.files[index],saved=await read('folders',t.id);if(!saved)throw Error('Torna a vincular la carpeta per accedir als documents.');if(saved.handle){if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís per llegir el document.');let h=saved.handle;const parts=meta.path.split('/');for(const part of parts.slice(0,-1))h=await h.getDirectoryHandle(part);return await(await h.getFileHandle(parts.at(-1))).getFile()}const f=saved.files?.find(f=>f.path===meta.path)?.file;if(!f)throw Error('Document no disponible. Actualitza la carpeta.');return f}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function template(kind){const content=kind==='people'?'Nom;Telefon;Origen;Arribada;Bitllet;Check-in;Recollida;Aparcament;Notes\r\nPersona exemple;600000000;Girona;Divendres 14:30 - Aeroport;Pendent;Pendent;;;\r\n':'Vehicle;Conductor;Telefon;Origen;Hora;Trajecte;Places;Passatgers;Aparcament;Notes\r\nFurgoneta 1;Conductor exemple;600000000;Girona;Divendres 08:00;Anada;7;;Pendent;Espai per al material\r\n';download(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}),`plantilla-${kind==='people'?'participants':'transports'}.csv`)}
function importPreview(text,kind){const records=csvRecords(text,kind),t=trip(),keys=Object.keys(records[0]);if(records.length>2000)throw Error('Importa un màxim de 2.000 files cada vegada.');modal(`Importar ${kind==='people'?'participants':'transports'}`,`<p>${records.length} fitxes detectades. Revisa les dades abans de continuar.</p><div class="csv-preview table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${records.slice(0,20).map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${records.length>20?'<p class="small">Es mostren les primeres 20 files.</p>':''}<div class="notice">S’afegiran només noms nous. Si el nom ja existeix, se saltarà la fila per conservar les teves correccions. Els passatgers d’un CSV de transports es guarden com a anotació.</div>`,async()=>{const list=kind==='people'?t.people:t.vehicles,known=new Set(list.map(x=>normalize(x.name)));let added=0;for(const r of records){if(known.has(normalize(r.name)))continue;list.push({...r,id:uid(),...(kind==='people'?{vehicle:''}:{})});known.add(normalize(r.name));added++}await persist();toast(`${added} fitxes afegides · ${records.length-added} duplicades omeses`)},'Confirmar importació')}
function backup(){download(new Blob([JSON.stringify({format:'equip-v0',exportedAt:new Date().toISOString(),trips:state.trips},null,2)],{type:'application/json'}),'equip-viatges-copia.json');toast('Còpia exportada. Els documents originals no s’inclouen.')}
const handlers={
'participant-itinerary':id=>{const t=trip(),p=t.people.find(p=>p.id===id);if(!p)return;modal('Itinerari · '+p.name,`<p>${esc(t.name)} · ${esc(participantRole(p.role))} · ${esc(p.travelMode||'Avió')}</p>${documents.journeySummary(t,p)}${['Anada','Tornada'].map(direction=>{const v=vehicleForPerson(t,p,direction);return `<section class="panel"><h3>${direction} · transport</h3>${v?`<p><strong>${esc(v.name)}</strong>${v.driverId===p.id?' · Condueixes tu':''}</p><dl class="detail-list"><div><dt>Conductor</dt><dd>${esc(v.driver||'Per assignar')}</dd></div><div><dt>Telèfon</dt><dd>${esc(v.phone||'Pendent')}</dd></div><div><dt>Sortida</dt><dd>${esc(v.origin||'Pendent')} · ${esc(v.departure||'Pendent')}</dd></div><div><dt>Recollida</dt><dd>${esc(v.pickupLocation||'Pendent')} · ${esc(v.pickupTime||'Pendent')}</dd></div></dl>`:'<p>Vehicle pendent d’assignar.</p>'}</section>`}).join('')}<section class="panel"><h3>Allotjament</h3><p>${esc(t.hotel||'Pendent de confirmar')}</p></section>${p.travelMode!=='Cotxe'?`<button type="button" class="button" data-action="person-checkin" data-id="${p.id}">Dades per al check-in</button>`:''}<p class="small muted">Vista de coordinació. L’accés individual amb login encara no està activat.</p>`,async()=>{},'Tancar')},'import-roster':()=>{rosterTarget=trip().id;$('#rosterInput').click()},'reset-roster':()=>{const t=trip(),cached=cachedRoster(t);if(cached)rosterPreview(t,cached.rows,cached.source);else{rosterTarget=t.id;$('#rosterInput').click()}},'dashboard-filter':value=>{dashboardFilter=value;render()},'new-trip':()=>tripForm(),'edit-trip':()=>tripForm(true),'open-trip':id=>{selected=id;tab='overview';render()},home:()=>{selected=null;render()},tab:id=>{tab=id;render()},'new-person':()=>personForm(),'edit-person':personForm,'new-vehicle':()=>vehicleForm(),'edit-vehicle':vehicleForm,'link-folder':linkFolder,'refresh-folder':refreshFolder,template,import:kind=>{importKind=kind;$('#csvInput').click()},backup,restore:()=>{if(documents.isBusy()){toast('Atura la lectura abans de restaurar una còpia.');return}$('#restoreInput').click()},
'download-file':async index=>{const t=trip(),f=await localFile(t,Number(index));download(f,t.files[index].name)},
'import-file':async index=>{const t=trip(),f=await localFile(t,Number(index)),text=await f.text();modal('Quines dades conté el fitxer?',`<div class="form-grid">${select('Tipus de fitxes','kind','people',[['people','Participants'],['vehicles','Transports']])}</div>`,async data=>{setTimeout(()=>{try{importPreview(text,data.kind)}catch(e){fail(e)}},0)},'Revisar dades')},
'delete-person':id=>{if(!confirm('Vols eliminar aquest participant?'))return;const t=trip();removeParticipant(t,id);$('#modal').close();return persist()},
'delete-vehicle':id=>{if(!confirm('Vols eliminar aquest vehicle? Els participants quedaran sense aquesta assignació.'))return;const t=trip();t.vehicles=t.vehicles.filter(v=>v.id!==id);t.people.forEach(p=>{if(p.vehicle===id)p.vehicle='';if(p.returnVehicle===id)p.returnVehicle=''});$('#modal').close();return persist()}
};
async function saveTrip(draft){const next={...state,trips:state.trips.map(t=>t.id===draft.id?draft:t)};await write('data','state',next);state=next;render()}
const documents=createDocumentFeatures({esc,field,select,modal,toast,read,persist,render,getTrip:trip,getState:()=>state,localFile,goToDocuments:()=>{tab='files';render()},goToParticipants:()=>{tab='people';render()},saveTrip:async draft=>{const next={...state,trips:state.trips.map(t=>t.id===draft.id?draft:t)};await write('data','state',next);state=next;render()}});
Object.assign(handlers,documents.handlers);
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){if(documents.isBusy()&&!['home','open-trip','tab','stop-reading','download-file','backup'].includes(el.dataset.action)){toast('Espera que acabi la lectura o atura-la abans de modificar les dades.');return}const fn=handlers[el.dataset.action];if(fn)Promise.resolve().then(()=>fn(el.dataset.id)).catch(fail)}});
$('#allTrips').onclick=handlers.home;$('#backup').onclick=backup;$('#restore').onclick=handlers.restore;$('#closeModal').onclick=$('#cancelModal').onclick=()=>$('#modal').close();
$('#modalForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(data))data[k]=data[k].trim();if('name'in data&&!data.name){toast('Indica un nom.');return}$('#submitModal').disabled=true;try{await submitAction(data);$('#modal').close()}catch(e){fail(e)}finally{$('#submitModal').disabled=false}};
$('#rosterInput').onchange=async e=>{try{const file=e.target.files[0],t=state.trips.find(t=>t.id===rosterTarget);if(!file||!t)return;const content=await extractDocument(file);rosterPreview(t,rosterRows(content.tables),file.name)}catch(e){fail(e)}finally{e.target.value=''}};
$('#csvInput').onchange=async e=>{try{const f=e.target.files[0];if(f){if(f.size>5*1024*1024)throw Error('El CSV supera els 5 MB.');importPreview(await f.text(),importKind)}}catch(e){fail(e)}finally{e.target.value=''}};
$('#folderInput').onchange=async e=>{try{const fs=Array.from(e.target.files);if(!fs.length)return;const t=state.trips.find(t=>t.id===folderTarget);if(!t)return;if(fs.length>2000)throw Error('Selecciona una carpeta amb menys de 2.000 fitxers.');if(fs.reduce((n,f)=>n+f.size,0)>150*1024*1024)throw Error('La còpia supera els 150 MB. Selecciona una carpeta més petita o fes servir Chrome per vincular-la sense copiar-la.');toast('Guardant els documents al navegador…');const files=fs.filter(f=>!f.webkitRelativePath.split('/').some(x=>x.startsWith('.'))).map(f=>({path:f.webkitRelativePath.split('/').slice(1).join('/'),file:f}));await write('folders',t.id,{files});t.folder={name:fs[0].webkitRelativePath.split('/')[0],mode:'copy',updated:Date.now()};t.files=files.map(({path,file:f})=>({path,name:f.name,size:f.size,modified:f.lastModified})).sort((a,b)=>a.path.localeCompare(b.path));await persist();await documents.analyze(t)}catch(e){fail(e)}finally{e.target.value=''}};
$('#restoreInput').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('La còpia és massa gran.');const data=JSON.parse(await f.text());if(data.format!=='equip-v0'||!Array.isArray(data.trips))throw Error('Aquest fitxer no és una còpia d’Equip.');for(const t of data.trips){if(typeof t.name!=='string'||!Array.isArray(t.people)||!Array.isArray(t.vehicles)||!t.people.every(p=>typeof p.name==='string')||!t.vehicles.every(v=>typeof v.name==='string'))throw Error('La còpia conté dades no vàlides.')}modal('Restaurar còpia',`<p>S’afegiran ${data.trips.length} viatges com a còpies noves. Els viatges actuals es conservaran.</p><p class="muted">Hauràs de tornar a vincular les carpetes dels documents.</p>`,async()=>{for(const source of data.trips){const t=structuredClone(source);t.id=uid();t.name+=' (còpia)';const ids=new Map();t.vehicles.forEach(v=>{const id=uid();ids.set(v.id,id);v.id=id});const personIds=new Map();t.people.forEach(p=>{const id=uid();personIds.set(p.id,id);p.id=id;p.vehicle=ids.get(p.vehicle)||''});for(const r of Object.values(t.readings||{})){r.confirmed=(r.confirmed||[]).map(c=>({...c,personId:personIds.get(c.personId)})).filter(c=>c.personId);r.proposals=(r.proposals||[]).map(c=>({...c,personId:personIds.get(c.personId)||''}))}t.files=[];t.folder=null;state.trips.push(t)}await persist();toast('Còpia restaurada')},'Restaurar')}catch(e){fail(e)}finally{e.target.value=''}};
try{state=await read('data','state')||{trips:[]};const upgraded=structuredClone(state);let created=0,linked=0,updated=0;for(const t of upgraded.trips){if(t.rosterMode!=='excel'){t.rosterMode='excel';updated++;}const result=syncDetectedParticipants(t);created+=result.added;linked+=result.linked;updated+=result.updated}if(created||linked||updated){await write('data','state',upgraded);state=upgraded}render();if(created)toast(`${created} participants creats a partir dels documents ja llegits.`)}catch(e){$('#app').innerHTML=empty('No es pot obrir l’espai local','Activa l’emmagatzematge del navegador i torna a carregar la pàgina. Les dades no es poden guardar en aquesta sessió.');fail(e)}
